<?php namespace App\Controllers; class Activity extends BaseController{public function index(){if($r=$this->mustAdmin())return $r;$db=db_connect();$rows=$db->table('activity_logs a')->select('a.*,u.name user_name,u.email')->join('users u','u.id=a.user_id','left')->orderBy('a.id','DESC')->limit(500)->get()->getResultArray();return $this->render('activity/index',['pageTitle'=>'Activity Log','rows'=>$rows]);}}